@@ -0,0 +1,79 @@
+name: zombie
+description: >
+  Shambling zombie: hunched forward, arms reaching out, torn rag shirt with a blood stain, faded jeans,
+  sickly green skin, sunken glowing eyes, patchy dark hair. Top-down 3/4 view, 8 headings, 6-frame
+  shamble where the legs drag in turn and the arms sway (the torso stays planted, so nothing jumps).
+size: [44, 48]
+pivot: [22, 41]
+origin: [0, 0, 0]            # between the feet, on the ground
+directions: 8
+outline: auto
+status: draft
+style_version: 1
+tags: [enemy, character]
+
+materials:
+  skin:  { keys: ["8", "9", "a", "b"] }
+  shirt: { keys: ["s", "t", "u", "v"] }
+  jeans: { keys: ["c", "d", "e", "f"] }
+  shoe:  { keys: ["g", "h", "i"] }
+  hair:  { keys: ["1", "2", "3"] }
+  blood: { keys: ["o", "p", "q"] }
+  eye:   { keys: ["r"] }
+
+parts:
+  # legs: jeans over dark shoes; each leg moves as one part
+  - box: { from: [-2, 2, 0], to: [3, 4, 2], material: shoe }
+    id: left_leg
+  - box: { from: [-1, 2, 3], to: [1, 4, 14], material: jeans }
+    id: left_leg
+  - box: { from: [-2, -4, 0], to: [3, -2, 2], material: shoe }
+    id: right_leg
+  - box: { from: [-1, -4, 3], to: [1, -2, 14], material: jeans }
+    id: right_leg
+  - box: { from: [-2, -5, 14], to: [2, 5, 16], material: jeans }      # hips
+  # hunched torso: round belly, the chest leans forward
+  - ellipsoid: { center: [0, 0, 20], radii: [3, 5, 5], material: shirt }
+  - ellipsoid: { center: [2, 0, 25], radii: [3, 6, 4], material: shirt }
+  - box: { from: [-2, 3, 16], to: [2, 5, 17], material: skin }         # torn hem shows skin
+  - box: { from: [4, -3, 22], to: [5, 0, 26], material: blood }        # stain on the chest
+  - box: { from: [3, 1, 18], to: [3, 2, 20], material: blood }
+  # arms reaching forward, hands drooping
+  - box: { from: [1, 6, 23], to: [5, 8, 26], material: shirt }
+    id: left_arm
+  - box: { from: [6, 6, 23], to: [12, 8, 25], material: skin }
+    id: left_arm
+  - box: { from: [12, 6, 21], to: [13, 8, 23], material: skin }
+    id: left_arm
+  - box: { from: [1, -8, 23], to: [5, -6, 26], material: shirt }
+    id: right_arm
+  - box: { from: [6, -8, 23], to: [12, -6, 25], material: skin }
+    id: right_arm
+  - box: { from: [12, -8, 21], to: [13, -6, 23], material: skin }
+    id: right_arm
+  # drooping head, pushed forward
+  - box: { from: [3, -1, 28], to: [4, 1, 29], material: skin }         # neck
+    id: head
+  - ellipsoid: { center: [5, 0, 33], radii: [5, 5, 5], material: skin }
+    id: head
+  - ellipsoid: { center: [2, 1, 35], radii: [3, 4, 3], material: hair }  # patchy hair, back and top
+    id: head
+  - box: { from: [5, -3, 37], to: [6, -2, 38], material: hair }
+    id: head
+  - box: { from: [10, 1, 33], to: [10, 2, 34], material: eye }         # sunken glowing eyes
+    id: head
+  - box: { from: [10, -2, 33], to: [10, -1, 34], material: eye }
+    id: head
+  - box: { from: [10, -1, 30], to: [10, 1, 31], material: blood }      # open mouth
+    id: head
+
+animations:
+  walk:
+    fps: 6
+    poses:
+      - { left_leg: { offset: [2, 0, 0] }, right_leg: { offset: [-1, 0, 0] }, left_arm: { offset: [0, 0, 1] } }
+      - { left_leg: { offset: [1, 0, 0] }, right_leg: { offset: [0, 0, 0] }, head: { offset: [0, 0, -1] } }
+      - { left_leg: { offset: [0, 0, 0] }, right_leg: { offset: [1, 0, 0] }, right_arm: { offset: [0, 0, -1] } }
+      - { left_leg: { offset: [-1, 0, 0] }, right_leg: { offset: [2, 0, 0] }, right_arm: { offset: [0, 0, 1] } }
+      - { left_leg: { offset: [0, 0, 0] }, right_leg: { offset: [1, 0, 0] }, head: { offset: [0, 0, -1] } }
+      - { left_leg: { offset: [1, 0, 0] }, right_leg: { offset: [0, 0, 0] }, left_arm: { offset: [0, 0, -1] } }

